import{_ as t,l as s,o as e,c,v as o,p as l,x as r,d as n,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Aho–Corasick","description":"","frontmatter":{"title":"Aho–Corasick","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aho-corasick.md","filePath":"cs/aho-corasick.md","lastUpdated":1789023840000}'),p={name:"cs/aho-corasick.md"};function A(_,a,k,m,B,E){const i=s("Mermaid");return e(),c("div",null,[a[1]||(a[1]=o('<h1 id="aho–corasick" tabindex="-1">Aho–Corasick <a class="header-anchor" href="#aho–corasick" aria-label="Permalink to &quot;Aho–Corasick&quot;">​</a></h1><div class="epigraph"><p>多模式先建成一棵带失败边的 trie；扫文本一次，沿转移与失败链输出所有命中。</p><footer>—— 据 Aho and Corasick, Efficient String Matching: An Aid to Bibliographic Search, 1975；CLRS 第 32 章整理</footer></div><p>上一课<a href="/cs/boyer-moore">Boyer–Moore</a>优化单模式跳读。\\(k\\) 个模式各跑一遍，总代价随 \\(k\\) 倍增，且共享前缀被重复比。本课不重做坏字符表。缺口是<strong>一机多模式</strong>：把 \\(P_1,\\ldots,P_k\\) 做成自动机，扫 \\(T\\) 线性于 \\(n\\) 加命中次数。后课离开串，进入贪心范式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/trie">Trie</a> 已能插入多个串。匹配时失配不能只退回根：当前节点代表的前缀的真后缀可能是另一模式的前缀。Aho–Corasick：每个节点一条失败边，指向「最长真后缀」对应的节点（KMP 的 \\(\\pi\\) 在树上的推广）。扫描：\\(T\\) 的下一字符有转移则走，否则跟失败边直到有或到根。节点若标记模式结束（或失败链上有结束），报告命中。</p><p>缺口是失败函数，不是再写 \\(k\\) 次 KMP。预处理对模式总长 \\(m\\) 线性（字母表当常数或用 map 则多对数）。扫描 \\(O(n+z)\\)，\\(z\\) 为输出个数。</p><h3 id="失败边不是父指针" tabindex="-1">失败边不是父指针 <a class="header-anchor" href="#失败边不是父指针" aria-label="Permalink to &quot;失败边不是父指针&quot;">​</a></h3><p>父指针回退会丢掉「后缀也是前缀」。失败边可能跳到另一分支。输出链：沿失败边收集所有结束标记，避免漏掉被当前前缀包含的短模式。</p><p><span class="marginnote">Aho–Corasick 1975，CACM。与 KMP 同一自匹配思想，对象从串换成 trie。后课词法的「多种记号」是正则并，不是本课的精确多模式词典。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>将模式插入 trie，根的失败为根。BFS 按层算失败：孩子 \\(c\\) 的失败 = 父失败沿 \\(c\\) 能走到的节点。再扫 \\(T\\)。</p>',11)),(e(),l(h,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PS%5B%22%E6%A8%A1%E5%BC%8F%E9%9B%86%22%5D%20--%3E%20TR%5B%22Trie%22%5D%0A%20%20TR%20--%3E%20FAIL%5B%22BFS%20%E5%A4%B1%E8%B4%A5%E8%BE%B9%22%5D%0A%20%20FAIL%20--%3E%20SCAN%5B%22%E4%B8%80%E6%AC%A1%E6%89%AB%20T%22%5D%0A%20%20SCAN%20--%3E%20OUT%5B%22%E6%B2%BF%E8%BE%93%E5%87%BA%E9%93%BE%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>二进制字母表或 Unicode 的转移表要权衡空间；本课渐近把 \\(|\\Sigma|\\) 当实现参数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>摊还：失败边使状态上的「当前匹配长度」不增得太快，与 KMP 的 \\(q\\) 同类。不要对每个位置把失败链走到底而不记账——输出链应预处理成直接链表。重叠命中（<code>aa</code> 在 <code>aaa</code>）必须都报，除非题目去重。</p><p>与 BM：多模式上 BM 没有这份自动机；词典检索用本课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做正则、不写近似、不处理通配符。失败函数假定精确字符相等。后课默认：多模式精确匹配一次扫描；贪心作为设计法的正确性从下一课单独论证，不再扫串。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多模式 = trie + 失败边（KMP 在树上）。</li><li>预处理线性于模式总长；扫描线性于文本加输出。</li><li>精确词典，不是正则词法。</li><li>出处：Aho and Corasick, 1975；CLRS 第 32 章。</li></ul>',8))])}const T=t(p,[["render",A]]);export{u as __pageData,T as default};
